function queueRandomEvent(state, phase) {
  const pool = RANDOM_EVENTS.filter((e) => e.phase === phase);
  if (pool.length === 0) return;

  // 过滤掉不满足条件的事件
  var eligible = pool.filter(function (e) {
    return !e.conditions || e.conditions(state);
